JSON_H = "-H \"Content-Type: application/json\" \\\n"
SPEC = {
 "series": "BUILD A REAL API", "episode": "EP 4", "title": "Validate requests with DTOs",
 "subtitle": "NestJS · class-validator", "color": (255, 159, 67), "title_size": 92, "theme": "char",
 "next": "Ep 5 · Hash passwords with bcrypt", "outro_sub": "Follow so you don't miss Ep 5", "seed": 91,
 "hot": {"dtos.": (255, 210, 63), "dto,": (255, 210, 63), "400": (255, 92, 92), "whitelist": (110, 255, 210)},
 "steps": [
  {"say": "Welcome back to Build a Real API, episode four. Right now, anyone can send our API anything. An empty title, a number, or a ten thousand character essay. Today, we validate every request with DTOs.",
   "cap": "Welcome back to Build a Real API, episode 4. Right now, anyone can send our API anything. An empty title, a number, or a 10,000-character essay. Today, we validate every request with DTOs.",
   "do": [("wait", 6.0), ("note", "Never trust the request body")]},
  {"say": "Watch this. An empty title gets saved straight into our database.",
   "do": [("term", "curl -X POST localhost:3000/tasks \\\n" + JSON_H + "-d '{\"title\":\"\"}'", ['{"id":5,"title":"","done":false,...}'])]},
  {"say": "Let's fix it. Install class validator and class transformer.",
   "cap": "Let's fix it. Install class-validator and class-transformer.",
   "do": [("clear",), ("term", "npm i class-validator class-transformer", ["added 4 packages in 3s"])]},
  {"say": "One setting first. In tsconfig, turn off strict property initialization. Nest fills in DTO properties at runtime, so we don't need an exclamation mark on every field.",
   "cap": "One setting first. In tsconfig, turn off strictPropertyInitialization. Nest fills in DTO properties at runtime, so we don't need a ! on every field.",
   "do": [("file", "tsconfig.json", "{\n  \"compilerOptions\": {\n    // ...other options\n    \"strictPropertyInitialization\": false\n  }\n}"), ("hl", 4, 4)]},
  {"say": "Now a DTO, or data transfer object. It describes exactly what a request body must look like. The title must be a string, it can't be empty, and it's at most one hundred characters.",
   "cap": "Now a DTO, or data transfer object. It describes exactly what a request body must look like. The title must be a string, it can't be empty, and it's at most 100 characters.",
   "do": [("open", "src/tasks/dto/create-task.dto.ts", ""), ("type", "import {\n  IsNotEmpty, IsString, MaxLength,\n} from 'class-validator';\n\nexport class CreateTaskDto {\n  @IsString()\n  @IsNotEmpty()\n  @MaxLength(100)\n  title: string;\n}")]},
  {"say": "For updates, done must be a real boolean. Not the string true, and not the number one.",
   "do": [("open", "src/tasks/dto/update-task.dto.ts", ""), ("type", "import { IsBoolean } from 'class-validator';\n\nexport class UpdateTaskDto {\n  @IsBoolean()\n  done: boolean;\n}")]},
  {"say": "In main dot ts, turn on the validation pipe for the whole app. Whitelist strips out any extra fields we didn't define, so nobody can sneak data in.",
   "cap": "In main.ts, turn on the ValidationPipe for the whole app. whitelist strips out any extra fields we didn't define, so nobody can sneak data in.",
   "do": [("file", "src/main.ts", "import { ValidationPipe } from '@nestjs/common';\nimport { NestFactory } from '@nestjs/core';\nimport { AppModule } from './app.module';\n\nasync function bootstrap() {\n  const app =\n    await NestFactory.create(AppModule);\n  app.useGlobalPipes(\n    new ValidationPipe({ whitelist: true }),\n  );\n  await app.listen(3000);\n}\nbootstrap();"), ("hl", 8, 10)]},
  {"say": "In the controller, we swap body title for the whole DTO. Nest validates it before our code even runs.",
   "cap": "In the controller, we swap @Body('title') for the whole DTO. Nest validates it before our code even runs.",
   "do": [("file", "src/tasks/tasks.controller.ts", "  // ...imports, constructor and GET routes"), ("type", "\n\n  @Post()\n  create(@Body() dto: CreateTaskDto) {\n    return this.tasksService.create(dto.title);\n  }\n\n  @Patch(':id')\n  update(\n    @Param('id', ParseIntPipe) id: number,\n    @Body() dto: UpdateTaskDto,\n  ) {\n    return this.tasksService.update(id, dto.done);\n  }")]},
  {"say": "Let's test it. An empty title now gets a 400, with a clear message.",
   "do": [("clear",), ("term", "curl -X POST localhost:3000/tasks \\\n" + JSON_H + "-d '{\"title\":\"\"}'", ['{"message":["title should not be empty"],', ' "error":"Bad Request","statusCode":400}'])]},
  {"say": "Done as the word yes? Rejected.",
   "do": [("clear",), ("term", "curl -X PATCH localhost:3000/tasks/2 \\\n" + JSON_H + "-d '{\"done\":\"yes\"}'", ['{"message":["done must be a boolean value"],', ' "error":"Bad Request","statusCode":400}'])]},
  {"say": "And a valid task with an extra hack field? It's saved, but the extra field is silently stripped out.",
   "do": [("clear",), ("term", "curl -X POST localhost:3000/tasks \\\n" + JSON_H + "-d '{\"title\":\"Learn DTOs\",\"hack\":true}'", ['{"id":6,"title":"Learn DTOs","done":false,...}'])]},
  {"say": "Our API now rejects bad data automatically. In episode five, we start on authentication, by hashing passwords with bcrypt. Follow, so you don't miss it.",
   "cap": "Our API now rejects bad data automatically. In episode 5, we start on authentication, by hashing passwords with bcrypt. Follow, so you don't miss it.",
   "do": []},
 ],
}
